// Playwright skeleton (mobile viewport, data seed, flow steps)
test('mobile catalog E2E', async ({ page }) => {
  await page.setViewportSize({ width: 375, height: 812 });
  // seed data
  const user = await seedTestUser();
  await page.goto('https://shop.example.test');
  await page.fill('[data-test="search-input"]', 'lamp');
  await page.press('[data-test="search-input"]', 'Enter');
  await page.click('[data-test="price-filter-20-50"]');
  await page.click('[data-test="product-card-0"]');
  await page.click('[data-test="add-to-cart"]');
  await page.click('[data-test="checkout"]');
  await expect(page.locator('[data-test="order-total"]')).toBeVisible();
  // mock payment
  await page.route('**/payments/token', route => route.fulfill({ status: 200, body: JSON.stringify({ token: 'tok_test' }) }));
});
```

